(function(){
const key='almeida-customer-session';const rememberedEmailKey='almeida-customer-email';const root=document.querySelector('#account-page-content');let session=null;
const api=(path,opt={})=>fetch(ALMEIDA_SUPABASE_URL+path,{...opt,headers:{apikey:ALMEIDA_SUPABASE_KEY,Authorization:'Bearer '+(session?.access_token||ALMEIDA_SUPABASE_KEY),'Content-Type':'application/json',...(opt.headers||{})}}).then(async r=>{const raw=await r.text();let data=raw?JSON.parse(raw):null;if(!r.ok)throw Error(data?.message||data?.error_description||'Não foi possível carregar sua conta.');return data});
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const money=c=>(Number(c||0)/100).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});const first=v=>String(v||'').trim().split(/\s+/)[0]||'cliente';const addr=(a,k)=>a&&typeof a==='object'?a[k]||'':'';const status=s=>s==='pending'?'Aguardando confirmação':s==='confirmed'?'Venda confirmada':'Pedido cancelado';const icon=(symbol,label,target)=>`<button type="button" class="account-dashboard-card" data-account-target="${target}"><span class="account-tile-icon" aria-hidden="true">${symbol}</span><span>${label}</span></button>`;
function render(user,profile,orders){
 const name=profile?.full_name||user.user_metadata?.full_name||'',a=profile?.default_address||{};document.querySelector('#account-signout').hidden=false;
 root.innerHTML=`<section class="account-hero"><div class="account-hero-icon" aria-hidden="true">●</div><div><h1>Olá, ${esc(first(name))}</h1><p>Aqui você encontra todas as informações relacionadas à sua conta, como acompanhar seus últimos pedidos e adicionar novos endereços.</p></div></section><nav class="account-dashboard-cards" aria-label="Seções da conta">${icon('●','Meus dados','#dados')}${icon('▤','Meus pedidos','#pedidos')}${icon('⌖','Endereços','#enderecos')}${icon('♥','Favoritos','#favoritos')}</nav><div class="account-panels"><section id="dados" class="account-card account-panel"><div class="account-card-heading"><div><small>SEUS DADOS</small><h2>Dados pessoais</h2></div></div><form id="account-data-form" class="account-form"><label>Nome completo<input id="account-full-name" required value="${esc(name)}"></label><label>E-mail<input disabled value="${esc(user.email||profile?.email||'')}"></label><div class="account-form-row"><label>Data de nascimento<input id="account-birth-date" type="date" value="${esc(profile?.birth_date||'')}"></label><label>CPF<input id="account-cpf" inputmode="numeric" placeholder="000.000.000-00" maxlength="14" value="${esc(profile?.cpf||'')}"></label></div><label>Telefone<input id="account-phone" type="tel" placeholder="(32) 99999-9999" value="${esc(profile?.phone||'')}"></label><p id="account-data-feedback" class="account-feedback" role="status"></p><button class="primary" type="submit">Salvar meus dados</button></form></section><section id="enderecos" class="account-card account-panel"><div class="account-card-heading"><div><small>ENTREGA E RETIRADA</small><h2>Endereços</h2></div></div><form id="account-address-form" class="account-form"><label>Rua<input id="account-street" value="${esc(addr(a,'street'))}"></label><div class="account-form-row"><label>Número<input id="account-number" value="${esc(addr(a,'number'))}"></label><label>Bairro<input id="account-neighborhood" value="${esc(addr(a,'neighborhood'))}"></label></div><label>Referência<input id="account-reference" placeholder="Opcional" value="${esc(addr(a,'reference'))}"></label><button class="primary" type="submit">Salvar endereço</button></form></section><section id="pedidos" class="account-card account-panel account-orders"><div class="account-card-heading"><div><small>HISTÓRICO</small><h2>Meus pedidos</h2></div><span class="account-count">${orders.length}</span></div><div>${orders.length?orders.map(o=>`<article class="order-card"><div class="order-heading"><strong>Pedido #${esc(o.public_number)}</strong><span>${status(o.status)}</span></div><small>${new Date(o.created_at).toLocaleString('pt-BR')} · ${o.payment_method==='pix'?'PIX':o.payment_method==='cash'?'Dinheiro':'Cartão'}</small><p>${(o.order_items||[]).map(i=>`${esc(i.quantity)}× ${esc(i.product_name)} — ${esc(i.variant_name)} · ${money(i.line_total_cents)}`).join('<br>')}</p><b>Total: ${money(o.amount_due_cents)}</b></article>`).join(''):'<p class="muted">Você ainda não tem pedidos registrados.</p>'}</div></section><section id="favoritos" class="account-card account-panel"><div class="account-card-heading"><div><small>SELEÇÃO DO CLIENTE</small><h2>Favoritos</h2></div></div><p class="account-favorites-empty">Você ainda não adicionou produtos aos favoritos.</p></section></div>`;
 document.querySelector('#account-data-form').onsubmit=saveProfile;document.querySelector('#account-address-form').onsubmit=saveProfile;document.querySelector('#account-phone').oninput=formatPhone;document.querySelector('#account-cpf').oninput=formatCpf;
 const panels=[...document.querySelectorAll('.account-panel')];const cards=[...document.querySelectorAll('[data-account-target]')];
 const selectPanel=target=>{const id=String(target||'#dados').replace(/^#/,'');panels.forEach(panel=>{panel.hidden=panel.id!==id});cards.forEach(card=>card.classList.toggle('active',card.dataset.accountTarget==='#'+id));if(location.hash!==`#${id}`)history.replaceState(null,'',`${location.pathname}${location.search}#${id}`)};
 cards.forEach(button=>button.onclick=()=>selectPanel(button.dataset.accountTarget));selectPanel(location.hash&&panels.some(panel=>'#'+panel.id===location.hash)?location.hash:'#dados');
}
function renderLogin(message=''){
 document.querySelector('#account-signout').hidden=true;const remembered=localStorage.getItem(rememberedEmailKey)||'';
 root.innerHTML=`<section class="account-login-shell"><form id="account-login-form" class="account-login-card"><img class="account-login-logo" src="assets/logo.jpg" alt="Logo Almeida Construções"><h1>Acesse sua conta</h1><p>Informe seus dados para continuar</p><label>E-mail *<input id="account-login-email" type="email" autocomplete="email" required value="${esc(remembered)}"></label><label class="account-password-field">Senha *<input id="account-login-password" type="password" autocomplete="current-password" required minlength="6"></label><div class="account-login-options"><label><input id="account-remember" type="checkbox" ${remembered?'checked':''}> Lembrar meus dados</label><label><input id="account-show-password" type="checkbox"> Mostrar senha</label></div><p id="account-login-feedback" class="account-feedback" role="status">${esc(message)}</p><button class="account-login-submit" type="submit">ACESSAR CONTA</button><a class="account-register" href="conta.html?cadastro=1">Ainda não tenho cadastro</a><a class="account-forgot" href="index.html">Esqueci minha senha</a></form></section>`;
 const password=document.querySelector('#account-login-password');document.querySelector('#account-show-password').onchange=e=>{password.type=e.target.checked?'text':'password'};document.querySelector('#account-login-form').onsubmit=login;
}
function renderSignup(message=''){
 document.querySelector('#account-signout').hidden=true;
 root.innerHTML=`<section class="account-login-shell"><form id="account-signup-form" class="account-login-card account-signup-card"><img class="account-login-logo" src="assets/logo.jpg" alt="Logo Almeida Construções"><h1>Crie sua conta</h1><p>Preencha seus dados para continuar</p><label>Nome completo *<input id="signup-full-name" required autocomplete="name"></label><label>E-mail *<input id="signup-email" type="email" required autocomplete="email"></label><div class="account-form-row"><label>Data de nascimento *<input id="signup-birth-date" type="date" required autocomplete="bday"></label><label>CPF <input id="signup-cpf" inputmode="numeric" maxlength="14" placeholder="000.000.000-00"></label></div><label>Telefone *<input id="signup-phone" type="tel" required inputmode="tel" maxlength="15" placeholder="(32) 99999-9999" autocomplete="tel"></label><div class="account-section-title"><small>ENDEREÇO</small><h3>Onde você mora</h3></div><label>Rua *<input id="signup-street" required autocomplete="street-address"></label><div class="account-form-row"><label>Número *<input id="signup-number" required inputmode="numeric"></label><label>Bairro *<input id="signup-neighborhood" required></label></div><label>Referência <input id="signup-reference" placeholder="Opcional"></label><label class="account-password-field">Senha *<input id="signup-password" type="password" required minlength="6" autocomplete="new-password"></label><label><span><input id="signup-show-password" type="checkbox"> Mostrar senha</span></label><p id="signup-feedback" class="account-feedback" role="status">${esc(message)}</p><button class="account-login-submit" type="submit">CRIAR CONTA</button><a class="account-register" href="conta.html">Já tenho cadastro</a></form></section>`;
 document.querySelector('#signup-phone').oninput=formatPhone;document.querySelector('#signup-cpf').oninput=formatCpf;document.querySelector('#signup-show-password').onchange=e=>{document.querySelector('#signup-password').type=e.target.checked?'text':'password'};document.querySelector('#account-signup-form').onsubmit=signup;
}
async function signup(e){e.preventDefault();const feedback=document.querySelector('#signup-feedback'),button=document.querySelector('#account-signup-form button');const email=document.querySelector('#signup-email').value.trim(),password=document.querySelector('#signup-password').value;const profile={full_name:document.querySelector('#signup-full-name').value.trim(),birth_date:document.querySelector('#signup-birth-date').value,cpf:document.querySelector('#signup-cpf').value.trim(),phone:document.querySelector('#signup-phone').value.trim(),default_address:{street:document.querySelector('#signup-street').value.trim(),number:document.querySelector('#signup-number').value.trim(),neighborhood:document.querySelector('#signup-neighborhood').value.trim(),reference:document.querySelector('#signup-reference').value.trim()}};feedback.textContent='Criando sua conta...';feedback.classList.remove('error');button.disabled=true;try{const response=await fetch(ALMEIDA_SUPABASE_URL+'/auth/v1/signup?redirect_to='+encodeURIComponent('https://almeida-construcoes.pages.dev/'),{method:'POST',headers:{apikey:ALMEIDA_SUPABASE_KEY,'Content-Type':'application/json'},body:JSON.stringify({email,password,data:profile})});const raw=await response.text();let data=raw?JSON.parse(raw):{};if(!response.ok)throw Error(data.error_description||data.msg||data.message||'Não foi possível criar sua conta.');const next=data.session||data;if(next?.access_token){localStorage.setItem(key,JSON.stringify({...next,expires_at:Number(next.expires_at)||Math.floor(Date.now()/1000)+Number(next.expires_in||3600)}));localStorage.setItem(rememberedEmailKey,email);location.href='conta.html';return}feedback.textContent='Cadastro criado. Confirme seu e-mail pelo link recebido para acessar sua conta.';button.disabled=false}catch(x){feedback.textContent=x.message;feedback.classList.add('error');button.disabled=false}}
async function login(e){e.preventDefault();const feedback=document.querySelector('#account-login-feedback'),email=document.querySelector('#account-login-email').value.trim(),password=document.querySelector('#account-login-password').value,remember=document.querySelector('#account-remember').checked,submit=document.querySelector('.account-login-submit');feedback.textContent='Entrando...';feedback.classList.remove('error');submit.disabled=true;try{const response=await fetch(ALMEIDA_SUPABASE_URL+'/auth/v1/token?grant_type=password',{method:'POST',headers:{apikey:ALMEIDA_SUPABASE_KEY,'Content-Type':'application/json'},body:JSON.stringify({email,password})});const raw=await response.text();let data=raw?JSON.parse(raw):{};if(!response.ok)throw Error(data.error_description||data.msg||'E-mail ou senha incorretos.');if(!data.access_token)throw Error('Não foi possível iniciar a sessão.');if(remember)localStorage.setItem(rememberedEmailKey,email);else localStorage.removeItem(rememberedEmailKey);localStorage.setItem(key,JSON.stringify({...data,expires_at:Number(data.expires_at)||Math.floor(Date.now()/1000)+Number(data.expires_in||3600)}));location.reload()}catch(x){feedback.textContent=x.message;feedback.classList.add('error');submit.disabled=false}}
function formatPhone(e){let n=e.target.value.replace(/\D/g,'').slice(0,11);e.target.value=n.length>10?'('+n.slice(0,2)+') '+n.slice(2,7)+'-'+n.slice(7):n.length>2?'('+n.slice(0,2)+') '+n.slice(2):n}function formatCpf(e){let n=e.target.value.replace(/\D/g,'').slice(0,11);e.target.value=n.length>9?n.slice(0,3)+'.'+n.slice(3,6)+'.'+n.slice(6,9)+'-'+n.slice(9):n.length>6?n.slice(0,3)+'.'+n.slice(3,6)+'.'+n.slice(6):n.length>3?n.slice(0,3)+'.'+n.slice(3):n}
async function saveProfile(e){e.preventDefault();const feedback=document.querySelector('#account-data-feedback');feedback.textContent='Salvando...';feedback.classList.remove('error');try{await api('/rest/v1/profiles?id=eq.'+encodeURIComponent(session.user.id),{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({full_name:document.querySelector('#account-full-name').value.trim(),cpf:document.querySelector('#account-cpf').value.trim(),phone:document.querySelector('#account-phone').value.trim(),birth_date:document.querySelector('#account-birth-date').value||null,default_address:{street:document.querySelector('#account-street').value.trim(),number:document.querySelector('#account-number').value.trim(),neighborhood:document.querySelector('#account-neighborhood').value.trim(),reference:document.querySelector('#account-reference').value.trim()}})});feedback.textContent='Dados salvos com sucesso.'}catch(x){feedback.textContent=x.message;feedback.classList.add('error')}}
async function start(){try{session=JSON.parse(localStorage.getItem(key)||'null');if(new URLSearchParams(location.search).get('cadastro')==='1'){renderSignup();return}if(!session?.access_token){renderLogin();return}const user=await api('/auth/v1/user');session.user=user;const [profiles,orders]=await Promise.all([api('/rest/v1/profiles?select=full_name,email,cpf,phone,birth_date,default_address&id=eq.'+encodeURIComponent(user.id)),api('/rest/v1/orders?select=id,public_number,status,payment_method,amount_due_cents,created_at,order_items(product_name,variant_name,quantity,line_total_cents)&order=created_at.desc')]);render(user,profiles?.[0]||{},orders||[])}catch(x){localStorage.removeItem(key);session=null;renderLogin('Sua sessão expirou. Entre novamente para acessar sua conta.')}}
document.querySelector('#account-signout').onclick=async()=>{try{if(session?.access_token)await fetch(ALMEIDA_SUPABASE_URL+'/auth/v1/logout',{method:'POST',headers:{apikey:ALMEIDA_SUPABASE_KEY,Authorization:'Bearer '+session.access_token}})}finally{localStorage.removeItem(key);location.href='index.html'}};start();
})();

